-- Match codes by official label too (case-insensitive), not only by suffix or alias
create or replace function public.avetmiss_code(p_set text, p_label text)
returns text language sql stable set search_path = public as $$
  with v as (select nullif(btrim(p_label), '') as l),
  s as (select substring(l from '-\s*([0-9@]{1,4})\s*$') as suffix, l from v)
  select coalesce(
    (select suffix from s where suffix is not null
       and (exists(select 1 from avetmiss_codes c where c.code_set = p_set and c.code = suffix)
            or not exists(select 1 from avetmiss_codes c where c.code_set = p_set))),
    (select a.code from avetmiss_code_aliases a, s where a.code_set = p_set and a.alias = lower(s.l)),
    (select c.code from avetmiss_codes c, s where c.code_set = p_set and c.code = s.l),
    (select c.code from avetmiss_codes c, s where c.code_set = p_set and lower(c.label) = lower(s.l) limit 1)
  );
$$;

-- Searchable picker: type a few letters, get matching countries or languages
create or replace function public.avetmiss_code_search(p_set text, p_query text default '', p_limit integer default 20)
returns table(code text, label text)
language sql stable security definer set search_path = public as $$
  with q as (select lower(btrim(coalesce(p_query, ''))) as t, least(greatest(coalesce(p_limit, 20), 1), 50) as n),
  hits as (
    select c.code, c.label,
      case when q.t = '' then 3
           when c.code = q.t then 0
           when lower(c.label) = q.t then 0
           when lower(c.label) like q.t || '%' then 1
           when exists (select 1 from avetmiss_code_aliases a where a.code_set = c.code_set and a.code = c.code and a.alias like q.t || '%') then 1
           else 2 end as rank,
      c.sort
    from avetmiss_codes c, q
    where c.code_set = p_set and c.is_active
      and p_set in ('country','language')
      and (q.t = '' or c.code = q.t or lower(c.label) like '%' || q.t || '%'
           or exists (select 1 from avetmiss_code_aliases a where a.code_set = c.code_set and a.code = c.code and a.alias like q.t || '%'))
  )
  select code, label from hits, q order by rank, (code = '@@@@'), label limit (select n from q);
$$;
grant execute on function public.avetmiss_code_search(text, text, integer) to anon, authenticated;
comment on function public.avetmiss_code_search(text, text, integer) is 'Search ABS country (SACC) or language (ASCL) codes for the enrolment form pickers. Returns public reference data only.';

-- Home language: use the "other language" answer when the student does not speak English only
create or replace function public.enrollment_students_avetmiss()
returns trigger language plpgsql set search_path = public as $$
declare d jsonb := coalesce(new.details, '{}'::jsonb);
begin
  if tg_op = 'INSERT' then
    if new.student_number is null then
      new.student_number := 'SK' || lpad(nextval('public.student_number_seq')::text, 8, '0');
    end if;
  elsif old.student_number is not null and new.student_number is distinct from old.student_number
        and coalesce(current_setting('skyline.allow_student_number_change', true), '') <> 'on' then
    raise exception 'The student number % is permanent and cannot be changed', old.student_number
      using errcode = 'check_violation';
  elsif old.student_number is null and new.student_number is null then
    new.student_number := 'SK' || lpad(nextval('public.student_number_seq')::text, 8, '0');
  end if;

  if tg_op = 'INSERT' or new.details is distinct from old.details then
    new.sex_code               := coalesce(avetmiss_code('sex', d->>'gender'), new.sex_code);
    new.indigenous_status_code := coalesce(avetmiss_code('indigenous_status', d->>'atsi'), new.indigenous_status_code);
    new.school_level_code      := coalesce(avetmiss_code('school_level', d->>'school_level'), new.school_level_code);
    new.labour_force_code      := coalesce(avetmiss_code('labour_force', d->>'employment'), new.labour_force_code);
    new.disability_flag        := coalesce(avetmiss_code('flag', d->>'disability'), new.disability_flag);
    new.prior_education_flag   := coalesce(avetmiss_code('flag', d->>'prior_ed'), new.prior_education_flag);
    new.at_school_flag         := coalesce(avetmiss_code('flag', d->>'secondary_enrolled'), new.at_school_flag);
    new.home_language_code     := coalesce(avetmiss_code('language', d->>'language_home'),
                                           avetmiss_code('language', d->>'language_other'), new.home_language_code);
    new.birth_country_code     := coalesce(avetmiss_code('country', d->>'birth_country'), new.birth_country_code);
    if btrim(coalesce(d->>'year_completed', '')) ~ '^[0-9]{4}$' then
      new.school_level_year := btrim(d->>'year_completed');
    end if;
  end if;
  return new;
end $$;

-- Code existing students from what they already entered
update public.enrollment_students set
  home_language_code = coalesce(avetmiss_code('language', details->>'language_home'), avetmiss_code('language', details->>'language_other'), home_language_code),
  birth_country_code = coalesce(avetmiss_code('country', details->>'birth_country'), birth_country_code)
where details is not null;
